#!/usr/bin/env python3
"""Generated by stone render. Do not edit: change .cornerstone/config.yaml and render again.

Check K22: fail if a tracked instruction file has text that can make an agent harm the repo (D89).
It finds a package install or run from a registry, a download that runs in a shell, an API base
URL or proxy override, a URL to a host that is not in `instruction_text.hosts`, and hidden
Unicode. A loopback host always passes. An HTML comment gives a warning, but not
`<!-- ste-ignore -->`. A heading with `waiver (K22)` and text under it in the PR body passes the
findings, with a notice. A package in `instruction_text.packages` passes.
Run it in the repo root. Usage: instruction_text.py [--body FILE|-] [--format text|github]
"""

import argparse
import re
import subprocess
import sys
import unicodedata
from pathlib import Path
from urllib.parse import urlsplit

sys.dont_write_bytecode = True  # no __pycache__ folder in .cornerstone/lib
sys.path.insert(0, str(Path(__file__).resolve().parent.parent / "lib"))
try:
    from path_match import covers
except Exception:  # noqa: BLE001 - a missing or broken module must fail the check, not pass it
    print("K22: .cornerstone/lib/path_match.py is missing or broken. Run stone render.")
    sys.exit(1)

INSTRUCTION_FILES = ["**/[Aa][Gg][Ee][Nn][Tt][Ss].[Mm][Dd]", "**/[Cc][Ll][Aa][Uu][Dd][Ee].[Mm][Dd]", "**/[Cc][Ll][Aa][Uu][Dd][Ee].[Ll][Oo][Cc][Aa][Ll].[Mm][Dd]"]
HOSTS = ["brawblan.github.io"]
PACKAGES = []
LOOPBACK = {"localhost", "127.0.0.1", "::1", "0.0.0.0"}

ARGS = r"(?P<args>[^\n`|;&)]*)"
# Each form installs or runs a package. A form in RUNNERS runs one package: the first word.
INSTALL = re.compile(
    r"\b(?P<tool>(?:npm|pnpm|yarn|bun)\s+(?:install|i|add)|yarn\s+global\s+add"
    r"|npx|bunx|pnpx|uvx|(?:npm|pnpm)\s+(?:exec|x)|bun\s+x|(?:pnpm|yarn)\s+dlx"
    r"|pip(?:3(?:\.\d+)?)?\s+install|pipx\s+(?:install|run)|uv\s+(?:pip|tool)\s+(?:install|run)"
    r"|uv\s+add|poetry\s+add|conda\s+install|(?:gem|cargo|brew)\s+install|cargo\s+add"
    r"|go\s+(?:install|get|run)|apt(?:-get)?\s+install)\b" + ARGS, re.IGNORECASE)
RUNNERS = re.compile(r"^(?:npx|bunx|pnpx|uvx|npm\s+(?:exec|x)|pnpm\s+(?:exec|x|dlx)|bun\s+x"
                     r"|yarn\s+dlx|pipx\s+run|uv\s+tool\s+run|go\s+run)$", re.IGNORECASE)
PATH_OPTIONS = {"-r", "--requirement", "-c", "--constraint", "-e", "--editable"}  # pip and uv
FETCH = r"(?:curl|wget|iwr|irm|invoke-webrequest|invoke-restmethod)"
SHELL = r"(?:\S*/)?(?:ba|z|da|k|fi)?sh|python\d*|node|perl|ruby|iex|invoke-expression"
RUN_DOWNLOAD = re.compile(
    rf"\b{FETCH}\b[^\n`]*\|\s*(?:sudo(?:\s+-\S+)*\s+)?(?:env\s+)?(?:{SHELL})\b"
    rf"|[$<]\(\s*{FETCH}\b|\b(?:iex|invoke-expression)\b[^\n`]*\b{FETCH}\b", re.IGNORECASE)
OVERRIDE = re.compile(r"\b([A-Z][A-Z0-9_]*_(?:BASE_URL|API_URL|ENDPOINT)|(?:HTTPS?|ALL)_PROXY)"
                      r"(?:\s*[=:]\s*|\s+to\s+)[\"']?(?P<value>[^\s\"'`]+)")
URL = re.compile(r"\b(?:https?|wss?|ftp)://[^\s)>\]`\"'<]+", re.IGNORECASE)
FETCH_TARGET = re.compile(rf"\b{FETCH}\b(?:\s+-\S+)*\s+(?P<target>[a-z0-9.-]+\.[a-z]{{2,}}\S*)",
                          re.IGNORECASE)
HANGUL_FILLERS = {0x115F, 0x1160, 0x3164, 0xFFA0}
COMMENT = re.compile(r"<!--(?!\s*ste-ignore\s*-->)")
WAIVER = re.compile(r"^#{1,6}[ \t]+.*waiver \(k22\)", re.IGNORECASE)
EMPTY = {"", "none", "tbd", "n/a", "todo", "-"}


def package_name(token: str) -> str:
    """Return the name of a package token with no version: prettier@3 becomes prettier."""
    token = token.strip("'\"")
    head, _, _ = token[1:].partition("@") if token.startswith("@") else token.partition("@")
    name = ("@" + head) if token.startswith("@") else head
    return re.split(r"[=<>~!\[]", name, maxsplit=1)[0]


def registry_packages(tool: str, args: str) -> list[str]:
    """Return each argument that names a registry package, not an option or a local path."""
    words = args.split()
    if RUNNERS.match(" ".join(tool.split())):
        words = [next((word for word in words if not word.startswith("-")), "")]
    pip_like = tool.lower().startswith(("pip", "uv"))
    names, skip = [], False
    for token in words:
        if skip:
            skip = False
            continue
        if pip_like and token in PATH_OPTIONS:
            skip = True
            continue
        if not token or token.startswith((".", "/", "~", "-", "$", "<")):
            continue  # a path, an option, or a placeholder
        if package_name(token) not in PACKAGES:
            names.append(token)
    return names


def host_of(url: str) -> str:
    """Return the host of a URL as a parser reads it. ?, #, and \\ end the host."""
    try:
        return (urlsplit(url.replace("\\", "/")).hostname or "").lower().rstrip(".")
    except ValueError:
        return url


def host_allowed(host: str) -> bool:
    return host in LOOPBACK or any(host == item or host.endswith("." + item) for item in HOSTS)


def hidden_characters(line: str) -> list[int]:
    """Return the code points that a reader does not see. A ZWJ between emoji is not hidden."""
    found = []
    for index, char in enumerate(line):
        code = ord(char)
        if code == 0x200D:
            near = line[index - 1:index] + line[index + 1:index + 2]
            if near and all(ord(item) >= 0x2600 for item in near):
                continue
        if (unicodedata.category(char) == "Cf" or code in HANGUL_FILLERS or code == 0x034F
                or 0xE0100 <= code <= 0xE01EF):
            found.append(code)
    return found


def line_findings(line: str) -> list[tuple[str, str]]:
    """Return (level, message) for each finding in one line."""
    found = []
    for match in INSTALL.finditer(line):
        names = registry_packages(match.group("tool"), match.group("args"))
        if names:
            found.append(("error", f"installs or runs a package from a registry: "
                          f"{', '.join(names)}. Add it to instruction_text.packages if a human "
                          "trusts it."))
    if RUN_DOWNLOAD.search(line):
        found.append(("error", "runs a download in a shell or an interpreter."))
    for match in OVERRIDE.finditer(line):
        value = match.group("value")
        if host_of(value if "://" in value else "http://" + value) not in LOOPBACK:
            found.append(("error", f"sets {match.group(1)}, which can send the traffic of the "
                          "agent to another host."))
    hosts = [host_of(match.group(0)) for match in URL.finditer(line)]
    hosts += [host_of("http://" + match.group("target")) for match in FETCH_TARGET.finditer(line)
              if "://" not in match.group("target")]
    for host in dict.fromkeys(hosts):
        if not host_allowed(host):
            found.append(("error", f"has a URL to {host or 'a host that does not parse'}. The "
                          "host is not in instruction_text.hosts."))
    for code in hidden_characters(line):
        found.append(("error", f"has the hidden character U+{code:04X}."))
    if COMMENT.search(line):
        found.append(("warning", "has an HTML comment. A reader does not see it, but an agent "
                      "reads it."))
    return found


def instruction_files() -> list[str]:
    run = subprocess.run(["git", "ls-files", "-z"], capture_output=True, text=True, check=True)
    return sorted(path for path in run.stdout.split("\0") if path and covers(INSTRUCTION_FILES, path))


def has_waiver(body: str) -> bool:
    lines = body.splitlines()
    for number, line in enumerate(lines):
        if WAIVER.match(line):
            text = []
            for after in lines[number + 1:]:
                if after.lstrip().startswith("#"):
                    break
                text.append(after.strip())
            content = " ".join(item for item in text if item).strip(" .*_`:").lower()
            if content not in EMPTY:
                return True
    return False


def main(argv: list[str]) -> int:
    parser = argparse.ArgumentParser(prog="instruction_text.py")
    parser.add_argument("--body", help="The PR body: a file, or - for stdin.")
    parser.add_argument("--format", choices=["text", "github"], default="text")
    args = parser.parse_args(argv)
    body = ""
    if args.body == "-":
        body = sys.stdin.read()
    elif args.body:
        body = Path(args.body).read_text(encoding="utf-8")
    waived = has_waiver(body)
    errors = warnings = 0
    for path in instruction_files():
        text = Path(path).read_text(encoding="utf-8", errors="replace")
        for number, line in enumerate(text.splitlines(), start=1):
            for level, message in line_findings(line):
                if level == "error" and waived:
                    level = "notice"
                errors += level == "error"
                warnings += level == "warning"
                if args.format == "github":
                    print(f"::{level} file={path},line={number}::K22: {message}")
                else:
                    print(f"{path}:{number}: {level}: K22: {message}")
    if waived:
        print("K22: notice: the PR body has a Waiver (K22) section. A human reviews each finding.")
    print(f"K22: {errors} error(s), {warnings} warning(s).")
    return 1 if errors else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
